		function edit_ledger()
		{
			$(document).on('click','#btn_edit_ledger',function()
			{
				var ledger_id = $(this).attr('data-id');
				$.ajax(
				{
					url: '/layout/items/ledger_edit.php',
					method: 'POST',
					data: {ledger_id:ledger_id},
					datatype: 'JSON',
					success: function(data)
					{
						var res = $.parseJSON(data);
						$('#ledger_id').val(res[0]);
						$('#ledgerdesc').val(res[1]);
						$('#ledgerCode').val(res[2]);
						$('#tb_1_div').html(res[4]);
						$('#tb_2_div').html(res[6]);
						$('#tb_3_div').html(res[8]);
						$('#tb_4_div').html(res[10]);
						$('#tb_5_div').html(res[12]);
						$('#ledgertype').val(res[13]);
						$('#ledgeraddress').val(res[14]);
						$('#ledgeremail').val(res[15]);
						$('#ledgerphone').val(res[16]);
						$('#ledgerstatus').val(res[17]);
						$('#show_balance').val(res[18]);
						$('#ledger_create_modal_header').html('Ledger Update');
						if (res[11] == 1)
						{
							$('#ledger_type_div').show();
							$("ledger_type_div").addClass("col-md-4 mb-4");
							$("ledger_code_div").addClass("col-md-2 mb-2");
						}
						else{
							$('#ledger_type_div').hide();
							$("ledger_code_div").addClass("col-md-6 mb-6");
						};
						$('#ledger_opening_balance').val(res[19]);
						$('#ledger_opening_date').val(res[20]);
						$('#ledger_opening_state').val(res[21]);
						$('#ledger_company_id').val(res[22]);
						$('#ledger_update_btn').show();
						$('#ledger_execute_btn').hide();
						$('#ledger_save_btn').hide();
						$('#ledgercreatemodal').modal('show');
					}
				})
			}) 
		}

