		function age()
		{
			$(document).on('change','#DOB',function()
			{
				var dob = new Date($('#DOB').val());
				var today = new Date(); 
				var diff = parseInt((today-dob)/(1000*60*60*24*30));

				var date_of_birth = $('#DOB').val();
				if(date_of_birth != '')
				{
					if(diff > 11)
				    {
						var str=date_of_birth.split('-');    
						var firstdate=new Date(str[0],str[1],str[2]);
						var today = new Date();        
						var dayDiff = Math.ceil(today.getTime() - firstdate.getTime()) / (1000 * 60 * 60 * 24 * 365);
						var age = parseInt(dayDiff)+' years';
					}
					else
					{
						var age = diff+' months';
					};
					$('#age').val(age);
				}
			}); 
		}

