		function tax_schedule_entry()
		{
			$(document).on('keyup','.CI, .Rate',function(){
				if(isNaN(parseFloat($('#CI_1').val())))
				{var CI_1 = 0;}else{var CI_1 = parseFloat($('#CI_1').val());};
				
				if(isNaN(parseFloat($('#CI_2').val())))
				{var CI_2 = 0;}else{var CI_2 = parseFloat($('#CI_2').val());};
				
				if(isNaN(parseFloat($('#CI_3').val())))
				{var CI_3 = 0;}else{var CI_3 = parseFloat($('#CI_3').val());};
						
				if(isNaN(parseFloat($('#CI_4').val())))
				{var CI_4 = 0;}else{var CI_4 = parseFloat($('#CI_4').val());};
					
				if(isNaN(parseFloat($('#CI_5').val())))
				{var CI_5 = 0;}else{var CI_5 = parseFloat($('#CI_5').val());};
					
				if(isNaN(parseFloat($('#CI_6').val())))
				{var CI_6 = 0;}else{var CI_6 = parseFloat($('#CI_6').val());};
					
				if(isNaN(parseFloat($('#CI_7').val())))
				{var CI_7 = 0;}else{var CI_7 = parseFloat($('#CI_7').val());};

				if(isNaN(parseFloat($('#Rate_1').val())))
				{var Rate_1 = 0;}else{var Rate_1 = parseFloat($('#Rate_1').val());};
					
				if(isNaN(parseFloat($('#Rate_2').val())))
				{var Rate_2 = 0;}else{var Rate_2 = parseFloat($('#Rate_2').val());};
					
				if(isNaN(parseFloat($('#Rate_3').val())))
				{var Rate_3 = 0;}else{var Rate_3 = parseFloat($('#Rate_3').val());};
					
				if(isNaN(parseFloat($('#Rate_4').val())))
				{var Rate_4 = 0;}else{var Rate_4 = parseFloat($('#Rate_4').val());};
					
				if(isNaN(parseFloat($('#Rate_5').val())))
				{var Rate_5 = 0;}else{var Rate_5 = parseFloat($('#Rate_5').val());};
					
				if(isNaN(parseFloat($('#Rate_6').val())))
				{var Rate_6 = 0;}else{var Rate_6 = parseFloat($('#Rate_6').val());};
					
				if(isNaN(parseFloat($('#Rate_7').val())))
				{var Rate_7 = 0;}else{var Rate_7 = parseFloat($('#Rate_7').val());};

				var tax_1 = CI_1 * Rate_1;
				var tax_2 = CI_2 * Rate_2;
				var tax_3 = CI_3 * Rate_3;
				var tax_4 = CI_4 * Rate_4;
				var tax_5 = CI_5 * Rate_5;
				var tax_6 = CI_6 * Rate_6;
				var tax_7 = CI_7 * Rate_7;

				$('#Tax_1').val(tax_1);
				$('#Tax_2').val(tax_2);
				$('#Tax_3').val(tax_3);
				$('#Tax_4').val(tax_4);
				$('#Tax_5').val(tax_5);
				$('#Tax_6').val(tax_6);
				$('#Tax_7').val(tax_7);

				$('#CT_1').val(tax_1);
				$('#CT_2').val(tax_1 + tax_2);
				$('#CT_3').val(tax_1 + tax_2 + tax_3);
				$('#CT_4').val(tax_1 + tax_2 + tax_3 + tax_4);
				$('#CT_5').val(tax_1 + tax_2 + tax_3 + tax_4 + tax_5);
				$('#CT_6').val(tax_1 + tax_2 + tax_3 + tax_4 + tax_5 + tax_6);
				//$('#CT_7').val(tax_1 + tax_2 + tax_3 + tax_4 + tax_5 + tax_6 + tax_7);

				$('#CCI_1').val(CI_1);
				$('#CCI_2').val(CI_1 + CI_2);
				$('#CCI_3').val(CI_1 + CI_2 + CI_3);
				$('#CCI_4').val(CI_1 + CI_2 + CI_3 + CI_4);
				$('#CCI_5').val(CI_1 + CI_2 + CI_3 + CI_4 + CI_5);
				$('#CCI_6').val(CI_1 + CI_2 + CI_3 + CI_4 + CI_5 + CI_6);
				//$('#CCI_7').val(CI_1 + CI_2 + CI_3 + CI_4 + CI_5 + CI_6 + CI_7);
			});
		}

