		function employee_auto_entry()
		{
			$(document).on('keyup change','#employee_basic_salary, #employee_paye_status, #employee_ssf_remark',function()
			{
				var ssf_remarks = $('#employee_ssf_remark').val();
				var tax_remarks = $('#employee_paye_status').val();
				if(isNaN(parseFloat($('#employee_basic_salary').val())))
				{
					var basic_salary = 0;
				}else
				{
					var basic_salary = parseFloat($('#employee_basic_salary').val());
				};

				if(isNaN(parseFloat($('#employee_fuel_allowance').val())))
				{
					var fuel_allowance = 0;
				}else
				{
					var fuel_allowance = parseFloat($('#employee_fuel_allowance').val());
				};

				if(isNaN(parseFloat($('#employee_clothing_allowance').val())))
				{
					var clothing_allowance = 0;
				}else
				{
					var clothing_allowance = parseFloat($('#employee_clothing_allowance').val());
				};

				if(isNaN(parseFloat($('#employee_other_allowance').val())))
				{
					var other_allowance = 0;
				}else
				{
					var other_allowance = parseFloat($('#employee_other_allowance').val());
				};

				if(isNaN(parseFloat($('#employee_welfare').val())))
				{
					var welfare = 0;
				}else
				{
					var welfare = parseFloat($('#employee_welfare').val());
				};

				if(isNaN(parseFloat($('#employee_other_deductions').val())))
				{
					var other_deductions = 0;
				}else
				{
					var other_deductions = parseFloat($('#employee_other_deductions').val());
				};
				
				var daily_wage = parseFloat(basic_salary/27).toFixed(2);
				var hourly_wage = parseFloat(daily_wage/8).toFixed(2);
				if(ssf_remarks == 'Yes')
				{
					var ssf_contribution = parseFloat(basic_salary * 0.055);
					var ssf_employer = parseFloat(basic_salary * 0.13).toFixed(2);
					var ssf_2nd_tier = parseFloat(basic_salary * 0.05).toFixed(2);
					var ssf_1st_tier = parseFloat(basic_salary * 0.135).toFixed(2);
				}
				else
				{
					var ssf_contribution = 0;
					var ssf_employer = 0;
					var ssf_2nd_tier = 0;
					var ssf_1st_tier = 0;
				};
				var holiday_rate = parseFloat(hourly_wage * 2).toFixed(2);
				var day_67_rate = parseFloat(hourly_wage * 2).toFixed(2);
				var overtime_rate = parseFloat(hourly_wage * 1.5).toFixed(2);
				$('#employee_daily_wage').val(daily_wage);
				$('#employee_daily_wageD').val(daily_wage);
				$('#employee_hourly_wage').val(hourly_wage);
				$('#employee_hourly_wageD').val(hourly_wage);
				$('#employee_ssf_contribution').val(ssf_contribution);
				$('#employee_ssf_contributionD').val(ssf_contribution);
				$('#employee_ssf_employer').val(ssf_employer);
				$('#employee_ssf_employerD').val(ssf_employer);
				$('#employee_ssf_1st_tier').val(ssf_1st_tier);
				$('#employee_ssf_1st_tierD').val(ssf_1st_tier);
				$('#employee_ssf_2nd_tier').val(ssf_2nd_tier);
				$('#employee_ssf_2nd_tierD').val(ssf_2nd_tier);
				$('#employee_holiday_rate').val(holiday_rate);
				$('#employee_holiday_rateD').val(holiday_rate);
				$('#employee_day_67_rate').val(day_67_rate);
				$('#employee_day_67_rateD').val(day_67_rate);
				$('#employee_overtime_rate').val(overtime_rate);
				$('#employee_overtime_rateD').val(overtime_rate);
				var taxable_income = parseFloat(basic_salary - ssf_contribution).toFixed(2);
				var total_allowance = parseFloat(fuel_allowance + clothing_allowance + other_allowance).toFixed(2);
				var gross_salary = parseFloat(parseFloat(basic_salary) + parseFloat(total_allowance)).toFixed(2);
				var total_deduction = parseFloat(ssf_contribution + welfare + other_deductions).toFixed(2);
				var net_salary = parseFloat(basic_salary + fuel_allowance + clothing_allowance + other_allowance - ssf_contribution - welfare - other_deductions).toFixed(2);
				
				$('#employee_gross_salary').val(gross_salary);
				$('#employee_gross_salaryD').val(gross_salary);
				$('#employee_taxable_income').val(taxable_income);
				$('#employee_taxable_incomeD').val(taxable_income);
				$('#employee_total_allowance').val(total_allowance);
				$('#employee_total_allowanceD').val(total_allowance);
				$('#employee_total_deduction').val(total_deduction);
				$('#employee_total_deductionsD').val(total_deduction);
				if(tax_remarks == 'Yes' && basic_salary > 0)
				{
					$.ajax({
						url:'/layout/items/employee_tax.php',
						method:'POST',
						data:{
							basic_salary:basic_salary,
							ssf_contribution:ssf_contribution
						},
						success:function(data)
						{
							var paye = parseFloat(data).toFixed(2);
							$('#employee_tax').val(paye);
							$('#employee_taxD').val(paye);
							var take_home = parseFloat(net_salary - paye).toFixed(2);
							var grand_deduction = parseFloat(parseFloat(total_deduction) + parseFloat(paye)).toFixed(2);
							$('#employee_total_deduction').val(grand_deduction);
							$('#employee_total_deductionsD').val(grand_deduction);
							$('#employee_net_salary').val(take_home);
							$('#employee_net_salaryD').val(take_home);
						}
					});
				}
				else
				{
					var paye = parseFloat(0);
					$('#employee_tax').val(paye);
					$('#employee_taxD').val(paye);
					$('#employee_total_deduction').val(total_deduction);
					$('#employee_total_deductionsD').val(total_deduction);
					$('#employee_net_salary').val(net_salary);
					$('#employee_net_salaryD').val(net_salary);
				};
				
			});
		}
		
