		function employee_respnsibility_allowance()
		{
			$(document).on('change keyup','#employee_resp_allowance_status, #employee_resp_allowance_perc',function()
			{
				var remark = $('#employee_resp_allowance_status').val();
				var percentage = $('#employee_resp_allowance_perc').val();
				if(remark == 'Yes')
				{
					if(isNaN(parseFloat($('#employee_basic_salary').val())))
					{
						var basic_salary = 0;
					}
					else
					{
						var basic_salary = parseFloat($('#employee_basic_salary').val());
					};
					
					if(percentage != '' && percentage > 0)
					{
						if(isNaN(parseFloat($('#employee_resp_allowance_perc').val())))
						{
							var perc = 0;
						}
						else
						{
							var perc = parseFloat($('#employee_resp_allowance_perc').val());
						};
					}
					else
					{
						$('#employee_resp_allowance_perc').val(0.20);
						var perc = parseFloat($('#employee_resp_allowance_perc').val());
					};
					
						var responsibility_allowance = parseFloat(basic_salary * perc).toFixed(2);

						$('#employee_resp_allowance').val(responsibility_allowance);
				}
				else
				{
					$('#employee_resp_allowance').val(0);
				};
			});
		}
		
