		function delete_employee()
		{
			$(document).on('click','#btn_delete_employee',function()
			{
				var employee_id = $(this).attr('data-id');
				var currentRow = $(this).closest("tr");
				var name = currentRow.find("td:eq(1)").text();
				$('#item_delete_modal_title').text('Delete '+name);
				$('#item_delete_question').text('Are you sure you want to delete Employee: ' + name + '?');
				$('#item_delete_modal').modal('show');
				$(document).on('click','#item_delete_yes',function()
				{
					$.ajax({  
						url:'/layout/items/employee_delete.php',  
						type:'POST',  
						data:{
							employee_id:employee_id
						},
						success:function(data)
						{
							if(data == 'deleted')
							{
								$('#item_delete_question').text(name +' deleted successfully!');
								$('#item_delete_no').hide();
								$('#item_delete_yes').text('OK');
								$(document).on('click','#item_delete_yes',function()
								{
									$('#item_delete_modal').modal('hide');
									window.location.href="/layout/items/employee_list.php";
								});
							}
							else if(data == 'used')
							{
								$('#item_delete_question').text(name +' has payroll records, deletion is declined!');
								$('#item_delete_no').hide();
								$('#item_delete_yes').text('OK');
								$(document).on('click','#item_delete_yes',function()
								{
									$('#item_delete_modal').modal('hide');
									window.location.href="/layout/items/employee_list.php";
								});
							};
						}
					});
				});
				$(document).on('click','#item_delete_no',function(){
					$('#item_delete_modal').modal('hide');
				});
			});
		}

