		function update_time_sheet()
		{
			$(document).on('click','#time_sheet_update_btn',function()
			{
				var page = window.location.pathname;
				var time_sheet_branch_id = $('#time_sheet_branch_id').val();
				var time_sheet_date = $('#time_sheet_date').val();
				var last_tr_id = $("#time_sheet_employee_table tr:last").attr("id");
				var last_tr_select = $("#time_sheet_employee_table tr:last option:selected").val();
				if (time_sheet_branch_id !="" && time_sheet_branch_id != 0) 
				{
					if (time_sheet_date !="") 
					{
						if(last_tr_select =="" || last_tr_select ==0)
						{
							$('#'+last_tr_id+'').remove();
						};
						$.ajax({
							url:'/layout/vouchers/time_sheet_update.php',
							method:'POST',
							data:$('#time_sheet_create_form').serialize(),
							success:function(data)
							{
								$('#time_sheet_create_modal').modal('hide');
								$('#time_sheet_create_form').trigger('reset');
								window.location.href= page;
							}
						});
					} 
					else 
					{
						alert('Please the Date cannot be EMPTY!');
					};
				} 
				else 
				{
					alert('Please the Branch cannot be EMPTY!');
				};
			});
		}

		function display_time_sheet()
		{
			$(document).on('click','#btn_display_time_sheet',function(){
				var time_sheet_id = $(this).attr('data-id');
				var branch_id = $(this).attr('data-id1');
				var branch_name = $(this).attr('data-id3');
				var date = $(this).attr('data-id5');
				$.ajax({
					url:'/layout/vouchers/time_sheet_display.php',
					method:'POST',
					data:{
						time_sheet_id:time_sheet_id,
						branch_id:branch_id,
						branch_name:branch_name,
						date:date
					},
					success:function(data)
					{
						window.open('/layout/vouchers/time_sheet_list_list.php', '_blank');
					}
				});
			});
		}

		function search_time_sheet_by_date()
		{
			$(document).on('change','#time_sheet_search_from, #time_sheet_search_to',function(e){
				e.preventDefault();
				var start_date = $('#time_sheet_search_from').val();
				var end_date = $('#time_sheet_search_to').val();

				$.ajax({
		             url:'/layout/vouchers/time_sheet_search_by_date.php',
		             method:'POST',
		             data:{
						start_date:start_date,
						end_date:end_date
					},
		             success:function(data)
					{
						$('#time_sheet_list_table').html(data);
					}
		        });
			});
		}
		
		function delete_time_sheet()
		{
			$(document).on('click','#btn_delete_time_sheet',function()
			{
				var page = window.location.pathname;
				var time_sheet_id = $(this).attr('data-id');
				var currentRow = $(this).closest("tr");
				var date = currentRow.find("td:eq(0)").text();
				var branch = currentRow.find("td:eq(1)").text();
				var dept = currentRow.find("td:eq(2)").text();
				$('#item_delete_modal_title').text('Delete Time Sheet');
				$('#item_delete_question').text('Are you sure you want to delete Time Sheet for ' + branch + ' - '+ dept + ' created on '+ date + '? This will delete all the employee hours entered on this time sheet! Continue?');
				$('#item_delete_modal').modal('show');
				$(document).on('click','#item_delete_yes',function()
				{
					$.ajax({  
						url:'/layout/vouchers/time_sheet_delete.php',  
						type:'POST',  
						data:{time_sheet_id:time_sheet_id},
						success:function()
						{
							$('#item_delete_modal').modal('hide');
							window.location.href= page;
						}  
					});
				});
				$(document).on('click','#item_delete_no',function()
				{
					$('#item_delete_modal').modal('hide');
				});
			});
		}

