		function time_sheet_total_hours()
		{
			$(document).on('keyup','#time_sheet_list_overtime, #time_sheet_list_day67, #time_sheet_list_holiday',function(){
				if(isNaN(parseFloat($('#time_sheet_list_overtime').val())))
				{var overtime = 0;}else{var overtime = parseFloat($('#time_sheet_list_overtime').val());};

				if(isNaN(parseFloat($('#time_sheet_list_day67').val())))
				{var day67 = 0;}else{var day67 = parseFloat($('#time_sheet_list_day67').val());};

				if(isNaN(parseFloat($('#time_sheet_list_holiday').val())))
				{var holiday = 0;}else{var holiday = parseFloat($('#time_sheet_list_holiday').val());};
				
				var total = overtime + day67 + holiday;

				$('#time_sheet_list_total').val(total);
			})
		}

		function save_time_sheet_list()
		{
			$(document).on('click','#time_sheet_list_save_btn',function()
			{
				var page = window.location.pathname;
				var employee_id = $('#time_sheet_list_employee_id').val();
				var total = $('#time_sheet_list_total').val();
				var absent = $('#time_sheet_list_absent').val();
				if (employee_id !="" && employee_id != 0) 
				{
					if ((total !="" && total > 0) || absent > 0) 
					{
						$.ajax({
							url:'/layout/vouchers/time_sheet_list_save.php',
							method:'POST',
							data:$('#time_sheet_list_create_form').serialize(),
							success:function(data)
							{
								$('#time_sheet_list_create_modal').modal('hide');
								$('#time_sheet_list_create_form').trigger('reset');
								window.location.href= page;
							}
						});
					} 
					else 
					{
						alert('Please the Overtime, Day 6/7 or Holiday cannot be EMPTY!');
					};
				} 
				else 
				{
					alert('Please the Employee cannot be EMPTY!');
				};
			});
		}

