		function set_bonus_list_amount()
		{
			$(document).on('keyup','#bonus_list_basic_salary',function()
			{
				var basic_salary = parseFloat($(this).val());
				var calculation_type = $('#bonus_list_calculation_type').val();
				var percentage = parseFloat($('#bonus_list_percentage').val());
				if(calculation_type =='Percentage_Of_Salary')
				{
					var bonus = basic_salary * percentage;
				}
				else
				{
					var bonus = percentage;
				};
				$('#bonus_list_amount').val(bonus);
			});
		}

