		function update_pay_slip()
		{
			$(document).on('click','#loan_disbursement_update_btn',function()
			{
				var employee_id = $('#employee_id').val();
				var date = $('#date').val();
				var effective_date = $('#effective_date').val();
				var principal = $('#principal').val();
				var duration = $('#duration').val();
				var interest = $('#interest').val();
				var debit_ledger = $('#debit_ledger').val();
				var credit_ledger = $('#credit_ledger').val();
				if (employee_id !="" && employee_id != 0) 
				{
					if (date !="" && date != 0) 
					{
						if (effective_date !="" && effective_date != 0) 
						{
							if (principal !="" && principal != 0) 
							{
								if (duration !="" && duration != 0) 
								{
									if (interest !="") 
									{
										if (credit_ledger !="" && credit_ledger != 0) 
										{
											$.ajax({
												url:'/layout/vouchers/loan_disbursement_update.php',
												method:'POST',
												data:$('#loan_disbursement_create_form').serialize(),
												success:function(data)
												{
													$('#loan_disbursement_create_modal').modal('hide');
													$('#loan_disbursement_create_form').trigger('reset');
													window.open('/layout/vouchers/loan_disbursement_pdf.php', '_blank');
												}
											});
										} 
										else 
										{
											alert('Please the Credit Ledger cannot be EMPTY!');
										};
									} 
									else 
									{
										alert('Please the Interest cannot be EMPTY!');
									};
								} 
								else 
								{
									alert('Please the Duration cannot be EMPTY!');
								};
							} 
							else 
							{
								alert('Please the Princiapl cannot be EMPTY!');
							};
						} 
						else 
						{
							alert('Please the Effective Date cannot be EMPTY!');
						};
					} 
					else 
					{
						alert('Please the Transaction Date cannot be EMPTY!');
					};
				} 
				else 
				{
					alert('Please the Employee cannot be EMPTY!');
				};
			});
		}

