		function pay_slip_report_sending()
		{
			$(document).on('click','#pay_slip_report_ok_btn',function()
			{
				//var page = window.location.pathname;
				var type = $('#pay_slip_report_type').val();
				if($('#pay_slip_report_employee').val() !='' && $('#pay_slip_report_employee').val() > 0)
				{
					var employee = $('#pay_slip_report_employee').val();
					var branch = 0;
				}
				else
				{
					var employee = 0;
				};

				if($('#pay_slip_report_branch').val() !='' && $('#pay_slip_report_branch').val() > 0)
				{
					var branch = $('#pay_slip_report_branch').val();
					var employee = 0;
				}
				else
				{
					var branch = 0;
				};
				var start_date = $('#pay_slip_report_start_date').val();
				var end_date = $('#pay_slip_report_end_date').val();
				var execution_type = $('#pay_slip_execution_type').val();
				if (type !== "") 
				{
					if ((type == 'EMPLOYEE' && employee != '' && employee > 0) || type != 'EMPLOYEE') 
					{
						if ((type == 'BRANCH' && branch != '' && branch > 0) || type != 'BRANCH') 
						{
							if (start_date !='' && end_date != '' && end_date >= start_date) 
							{
								$.ajax({
									url:'/layout/reports/pay_slip_report_sending.php',
									method:'POST',
									data:{
										type:type,
										employee:employee,
										branch:branch,
										start_date:start_date,
										end_date:end_date
									},
									success:function(data)
									{
										$('#pay_slip_report_modal_form').trigger('reset');
										$('#pay_slip_report_modal').modal('hide');
										if(execution_type == 'DOWNLOAD')
										{
											window.open('/layout/reports/pay_slip_report_pdf.php', '_blank');
										}
										else if(execution_type == 'SEND_BY_MAIL')
										{
											window.open('/layout/reports/pay_slip_email.php', '_blank');
										};
									}
								});
							} 
							else 
							{
								$('#pay_slip_report_modal_warning').html('<h6 style=color:red;>Please check the Date!</h6>');
								$('#pay_slip_report_modal_warning').hide().slideDown().delay(2000).fadeOut();
							};
						} 
						else 
						{
							$('#pay_slip_report_modal_warning').html('<h6 style=color:red;>Please the BRANCH cannot be Empty!</h6>');
							$('#pay_slip_report_modal_warning').hide().slideDown().delay(2000).fadeOut();
						};
					}
					else 
					{
						$('#pay_slip_report_modal_warning').html('<h6 style=color:red;>Please the EMPLOYEE cannot be Empty!</h6>');
						$('#pay_slip_report_modal_warning').hide().slideDown().delay(2000).fadeOut();
					};
				} 
				else 
				{
					$('#pay_slip_report_modal_warning').html('<h6 style=color:red;>Please the report type cannot be Empty!</h6>');
					$('#pay_slip_report_modal_warning').hide().slideDown().delay(2000).fadeOut();
				};
			}); 
		}

