		function set_review_date()
		{
			$(document).on('change','#attend_review_date',function()
			{
				var date_review = $(this).val();
				var attend_id = $('#session_attend_id').val();
				var date_attend = $('#session_dateofadmission_attd').val();
				var page = window.location.pathname;
				if(date_review > date_attend)
				{
					$.ajax({  
						url:'/layout/attendance/attend_set_review_date.php',  
						type:'POST',  
						data:{
							date_review:date_review,
							attend_id:attend_id
						},
						success:function()
						{
							window.location.href= page;
						}
					});
				}
				else 
				{
					alert('Please the Review Date must be more than the Attendance Date');
				}
			});
		}
		
		function delete_attendance()
		{
			$(document).on('click','#btn_delete_attend',function(){
				var attend_id = $(this).attr('data-id');
				var page = window.location.pathname;
				$('#delete_question').text('Are you sure you want to delete Attendance No:' + attend_id);
				$('#delete_modal_title').text('Delete Attendance');
				$('#delete_modal').modal('show');
				$(document).on('click','#delete_yes',function()
				{
					$.ajax({  
						url:'/layout/attendance/attend_delete.php',  
						type:'POST',  
						data:{attend_id:attend_id},
						success:function()
						{
							$('#delete_modal').modal('hide');
							window.location.href= page;
						}
					});
				});
				$(document).on('click','#delete_no',function()
				{
					$('#delete_modal').modal('hide');
				});
			});
		}
		
