		function save_vitals()
		{
			$(document).on('click','#vitals_save_btn',function(e){
				e.preventDefault();
				var attend_id = $('#session_attend_id').val();
		    	var patient_id = $('#session_patient_id').val();
		    	var date_attend = $('#session_dateofadmission_attd').val();
			    var temp = $('#temp').val();
			    var bsystolic = $('#bsystolic').val();
			    var bdiastolic = $('#bdiastolic').val();
			    var pulse = $('#pulse').val();
			    var rrate = $('#rrate').val();
			    var weight = $('#weight').val();
			    var height = $('#height').val();
			    var oxygen = $('#oxygen').val();
			    var hipcirc = $('#hipcirc').val();
			    var abdcirc = $('#abdcirc').val();
			    var date = $('#v_date').val();
			    var time = $('#v_time').val();
			    var fbs = $('#fbs').val();
			    var rbs = $('#rbs').val();
			    var vitals_comment = $('#vitals_comment').val();

				var admission_date = $('#session_dateofadmission_attd').val();
				if (date >= admission_date) 
				{
					if (date >= date_attend) 
					{
						if (temp > 0) 
						{
							$.ajax({
							url:'/layout/attendance/vitals_save.php',
							method:'POST',
							data:{
								attend_id:attend_id,
								patient_id:patient_id,
								temp:temp,
								bsystolic:bsystolic,
								bdiastolic:bdiastolic,
								pulse:pulse,
								rrate:rrate,
								weight:weight,
								height:height,
								oxygen:oxygen,
								hipcirc:hipcirc,
								abdcirc:abdcirc,
								date:date,
								time:time,
								fbs:fbs,
								rbs:rbs,
								vitals_comment:vitals_comment
							},
							success:function(data)
								{
									$('#vitals_input_form').trigger('reset');
									view_current_vitals();
								}
							});} 
						else 
						{
							alert('Please enter Temperature!')
						};
					} 
					else 
					{
						alert('Please the date cannot be earlier than the attendance date!')
					};
				} 
				else 
				{
					alert('Please the Date ('+date+') cannot be earlier than the Admission Date ('+admission_date+')!');
				};
			});
		}

