		function history_medical_img_display()
		{
			$(document).on('click','#view_medical_history',function()
			{
				var attend_id = $(this).attr('data-id');
				var patient_id = $(this).attr('data-id1');
				$.ajax({  
		             url:'/layout/attendance/history_medical_img_display.php',
		             method:'POST',
		             datatype: 'JSON',
		             data:{
		             	attend_id:attend_id, 
		             	patient_id:patient_id
		             },
		             success:function(data){
		             	var result = $.parseJSON(data);
		             	$('#hx_med_list_img_display').html('');
						 for(var i = 0; i < result.length; i += 3) 
						 {
							 if(result[i+2] == 'pdf')
							 {
								 $('#hx_med_list_img_display').append('<iframe src="'+result[i]+'" width="1000" height="1100"></iframe><a href="#" id="delete_hx_med_image" data-id="'+result[i+1]+'" data-id1="'+attend_id+'" data-id2="'+patient_id+'">Clear</a>');
							 }
							 else
							 {
								 $('#hx_med_list_img_display').append('<img src="'+result[i]+'" width="1000" height="1100"><a href="#" id="delete_hx_med_image" data-id="'+result[i+1]+'" data-id1="'+attend_id+'" data-id2="'+patient_id+'">Clear</a>');
							 };
						 };
						$('#hx_med_img_display_modal').modal('show');
		             }  
	        	});
			}); 
		}
		
		function history_medical_img_display_clear()
		{
			$(document).on('click','#delete_hx_med_image',function()
			{
				var hx_med_img_id = $(this).attr('data-id');
				var attend_id = $(this).attr('data-id1');
				var patient_id = $(this).attr('data-id2');
				$('#history_delete_question').text('Are you sure you want to delete this Medical History?');
				$('#history_delete_modal').modal('show');
				$(document).on('click','#history_delete_yes',function()
				{
					$('#history_delete_modal').modal('hide');
					$.ajax({  
						url:'/layout/attendance/history_medical_img_display_clear.php',
						method:'POST',
						datatype: 'JSON',
						data:{
							hx_med_img_id:hx_med_img_id,
							patient_id:patient_id
						},
						success:function(data)
						{
							if(data > 0)
							{
								$.ajax({  
									url:'/layout/attendance/history_medical_img_display.php',
									method:'POST',
									datatype: 'JSON',
									data:{
										attend_id:attend_id, 
										patient_id:patient_id
									},
									success:function(data)
									{
										var result = $.parseJSON(data);
										$('#hx_med_list_img_display').html('');
										for(var i = 0; i < result.length; i += 3) 
										{
											if(result[i+2] == 'pdf')
											{
												$('#hx_med_list_img_display').append('<iframe src="'+result[i]+'" width="1000" height="1100"></iframe><a href="#" id="delete_hx_med_image" data-id="'+result[i+1]+'" data-id1="'+attend_id+'" data-id2="'+patient_id+'">Clear</a>');
											}
											else
											{
												$('#hx_med_list_img_display').append('<img src="'+result[i]+'" width="1000" height="1100"><a href="#" id="delete_hx_med_image" data-id="'+result[i+1]+'" data-id1="'+attend_id+'" data-id2="'+patient_id+'">Clear</a>');
											};
										};
										$('#hx_med_img_display_modal').modal('show');
									}
								});
							}
							else
							{
								window.location.href="/layout/attendance/history_sheet.php";
								$('#hx_med_img_display_modal').modal('hide');
							};
						}
					});
			    });
				$(document).on('click','#history_delete_no',function()
				{
					$('#history_delete_modal').modal('hide');
				});
				
			}); 
		}

