		function view_current_diagnosis()
		{
			if($('#session_attend_id').val() > 0){var attend_id = $('#session_attend_id').val();}else{var attend_id = 0;};
			if($('#session_age').val() > 0){var age = $('#session_age').val();}else{var age = 0;};
			if(attend_id > 0 && age > 0)
			{
				$.ajax({
					url:'/layout/attendance/diagnosis_current_view.php',
					method:'POST',
					data:{
						attend_id:attend_id,
						age:age
					},
					success:function(data)
					{
						$('#attend_diagnosis_table').html(data);
					}
				});
			};
		}

