						patient_id:patient_id,
						diagnosis:diagnosis,
						diag_date:diag_date,
						diag_gdrg:diag_gdrg,
						diag_comment:diag_comment,
						diag_amt:diag_amt,
						diag_sponsor:diag_sponsor,
						clinic:clinic,
