		function save_dialysis_sheet()
		{
			$(document).on('click','#dialysis_sheet_save_btn',function(e){
				e.preventDefault();
				var last_tr_id = $("#dialysis_sheet_list_table tr:last").attr("id");
				var last_tr_select = $("#dialysis_sheet_list_table tr:last option:selected").val();
				var treatment_time = $('#treatment_time').val();
				var connecting_nurse = $('#connecting_nurse').val();
				var disconnecting_nurse = $('#disconnecting_nurse').val();
				if (treatment_time !="") 
				{
					if (connecting_nurse !="") 
					{
						if (disconnecting_nurse !="") 
						{
							if(last_tr_select =="" || last_tr_select ==0)
							{
								$('#'+last_tr_id+'').remove();
							};
							$.ajax({
								url:'/layout/attendance/dialysis_sheet_save.php',
								method:'POST',
								data:$('#dialysis_sheet_modal_form').serialize(),
								success:function(data)
								{
									$('#dialysis_sheet_modal').trigger('reset');
									window.location.href="/layout/attendance/dialysis_sheet.php";
								}
							});
						} 
						else 
						{
							alert('Please the Disconnecting Nurse cannot be EMPTY!');
						};
					} 
					else 
					{
						alert('Please the Connecting Nurse cannot be EMPTY!');
					};
				} 
				else 
				{
					alert('Please the Treatment Time cannot be EMPTY!');
				};
			});
		}

