		function search_lab_list_modal()
		{
			$(document).on('click','#btn_lab_live_search',function()
			{
				var attend_id = $(this).attr('data-id');
				$.ajax({
					url:'/layout/attendance/drugs_validate_diagnosis.php',
					method:"POST",
					data:{attend_id:attend_id},
					success:function(data)
					{
						if(data == 'Diagnosis_Exist' || data == 'History_Exist')
						{
							$('#lab_list_search_modal_form').trigger('reset');
							$('#lab_list_search').focus();
							$('#lab_list_search_modal').modal('show');
						}
						else if(data == 'No_Diagnosis')
						{
							alert('Please enter Diagnosis before prescribing a drug!');
						}
						else if(data == 'No_History')
						{
							alert('Please enter History before prescribing a drug!');
						};
					}
				});
			});
		}

