		function estimate_drug()
		{
			$(document).on('keyup','.drug_list_qty_est, .drug_list_price_est',function()
			{
				var drug_list_id = $(this).attr('data-id');
				var qty_est = $('#drug_list_qty_est'+drug_list_id).val();
				var price_est = $('#drug_list_price_est'+drug_list_id).val();
				if(isNaN(qty_est)){var qty = 0;}else{var qty = qty_est;};
				if(isNaN(qty_est)){var price = 0;}else{var price = price_est;};
				
				if(price !=0 && qty !=0)
				{
					$.ajax({
						url:'/layout/attendance/drugs_estimate.php',
						method:'POST',
						datatype:'JSON',
						data:{drug_list_id:drug_list_id, qty:qty, price:price},
						success:function(data)
						{
							view_current_drugs();
						}
					});
				}
			});
		}

