		function drug_admin_status_modal()
		{
			$(document).on('click','#btn_suspend_drug_list, #btn_complete_drug_list,#btn_unsuspend_drug_list, #btn_uncomplete_drug_list',function()
			{
		    	var id = $(this).attr('id');
		    	var drug_list_id = $(this).attr('data-id1');
		    	var drug_id = $(this).attr('data-id2');
				$('#drug_admin_status_form').trigger('reset');
				if(id=="btn_suspend_drug_list")
				{
					$('#drug_admin_status_modal_header').text('Suspend Drug');
					$('#drug_admin_status_remarks').val('Suspend Drug Administration');
					$('#drug_admin_status_suspend_btn').show();
					$('#drug_admin_status_complete_btn').hide();
					$('#drug_admin_status_uncomplete_btn').hide();
					$('#drug_admin_status_unsuspend_btn').hide();
				}
				else if(id=="btn_complete_drug_list")
				{
					$('#drug_admin_status_modal_header').text('Complete Drug');
					$('#drug_admin_status_remarks').val('Complete Drug Administration');
					$('#drug_admin_status_suspend_btn').hide();
					$('#drug_admin_status_complete_btn').show();
					$('#drug_admin_status_uncomplete_btn').hide();
					$('#drug_admin_status_unsuspend_btn').hide();
				}
				else if(id=="btn_unsuspend_drug_list")
				{
					$('#drug_admin_status_modal_header').text('Unsuspend Drug');
					$('#drug_admin_status_remarks').val('Continue Drug Administration');
					$('#drug_admin_status_suspend_btn').hide();
					$('#drug_admin_status_complete_btn').hide();
					$('#drug_admin_status_uncomplete_btn').hide();
					$('#drug_admin_status_unsuspend_btn').show();
				}
				else if(id=="btn_uncomplete_drug_list")
				{
					$('#drug_admin_status_modal_header').text('Uncomplete Drug');
					$('#drug_admin_status_remarks').val('Drug Administration not completed');
					$('#drug_admin_status_suspend_btn').hide();
					$('#drug_admin_status_complete_btn').hide();
					$('#drug_admin_status_uncomplete_btn').show();
					$('#drug_admin_status_unsuspend_btn').hide();
				};
				$('#drug_admin_status_drug_list_id').val(drug_list_id);
				$('#drug_admin_status_drug_id').val(drug_id);
				$('#drug_admin_status_modal').modal('show');
			});
		}

