								$('#abortions').val(abortions);
								$('#induced').val(induced);
								$('#spontaneous').val(spontaneous);
								$('#lmp').val(lmp);
								$('#edd').val(edd);
								$('#blood_group').val(blood_group);
								$('#sickling').val(sickling);
								$('#geno_type').val(geno_type);
