				function sum_payment_item_amount()
				{
					$(document).on('keyup','.payment_dr_amt',function()
					{ 
						var sum=0;
						$('.payment_dr_amt').each(function()
						{
							var num = $(this).val().replace(',','');
							if(num !=0)
							{
								sum += parseFloat(num);
							}
						});
						$('#payment_amount').val(sum);
						$('#payment_amountD').val(sum);
					});
				}

