				function get_purchase_item_amount()
				{
					$(document).on('keyup', '.purch_price, .purch_qty', function()
					{  
		       			var i = $(this).attr("data-id"); 
		       			var qty = parseFloat($('#purch_qty'+i).val());
		       			var price = parseFloat($('#purch_price'+i).val());
						if(qty > 0 && price > 0)
						{
							var amt = parseFloat(qty * price).toFixed(2);
							$('#purch_amt'+i).val(amt);
							$('#purch_amtD'+i).val(amt);

							var sum=0;
							$('.purch_amt').each(function()
							{
								var num = $(this).val().replace(',','');
								if(num !=0)
								{
									sum += parseFloat(num);
								}
							});
							var amount = parseFloat(sum).toFixed(2);;
							$('#purch_amount').val(amount);
							$('#purch_amount_2').val(amount);
						};
		           	});
				}

				function delete_purchase_item_row()
				{
					$(document).on('click', '#delete_purchase_item', function()
					{  
		       			var button_id = $(this).attr("data-id");
		           		$('#'+button_id+'').remove();
						var sum=0;
						$('.purch_amt').each(function()
						{
							var num = $(this).val().replace(',','');
							if(num !=0)
							{
								sum += parseFloat(num);
							}
						});
		           		$('#purch_amount').val(sum);
		           		$('#purch_amount_2').val(sum);

		           	});
				}

				function get_purchase_discount()
				{
					$(document).on('keyup', '#purch_discount_perc, #purch_discount_amount', function()
					{
		       			var item_amt = $('#purch_amount').val();
		       			var disc_perc = $('#purch_discount_perc').val();
		       			var disc_amt = $('#purch_discount_amount').val();

						if(disc_perc > 0 && item_amt > 0)
						{
							var discount = disc_perc * item_amt;
						}
						else if(disc_perc == '' && disc_amt > 0 && item_amt > 0)
						{
							var discount = disc_amt;
						};

						var discount = parseFloat(discount).toFixed(2)
		       			$('#purch_discount_amount').val(discount);
		       			$('#purch_discount_amountD').val(discount);
		           	});
				}

				function save_purchase_invoice()
				{
					$(document).on('click','#purch_save_btn',function(e){
						e.preventDefault();
						var last_tr_id = $("#purchase_items_table tr:last").attr("id");
						var last_tr_select = $("#purchase_items_table tr:last option:selected").val();
						if(last_tr_select =="" || last_tr_select ==0)
						{
							$('#'+last_tr_id+'').remove();
						};
						var purch_debit = $('#purch_debit').val();
						var purch_credit = $('#purch_credit').val();
						var purch_amount = $('#purch_amount').val();
						var purch_supplied_by = $('#purch_supplied_by').val();
						var purch_ref_no = $('#purch_ref_no').val();
						var purch_date = $('#purch_date').val();
						var purch_received_by = $('#purch_received_by').val();
						var purch_narration = $('#purch_narration').val();
						var purch_desc = $('#purch_desc').val();
						if (purch_debit !=="") 
						{
							if (purch_credit !=="") 
							{
								if (purch_amount !=="") 
								{
									if (purch_supplied_by !=="") 
									{
										if (purch_ref_no !=="") 
										{
											if (purch_date !=="") 
											{
												if (purch_received_by !=="") 
												{
													if (purch_desc !=="") 
													{
														$.ajax({
												             url:'/layout/vouchers/purchases_save.php',
												             method:'POST',
												             data:$('#purchases_create_form').serialize(),
												             success:function(data)
													             {
													             	$('#purchases_create_form').trigger('reset');
													             	window.location.href="/layout/vouchers/purchases_list.php";
													             }
												             });
													} 
													else 
													{
														alert('Please select an item purchased!');
													}
												} 
												else 
												{
													alert('Please type the name of the person receiving the goods!');
												}
											} 
											else 
											{
												alert('Please select the date of purchase!');
											}
										} 
										else 
										{
											alert('Please type the supplier invoice number!');
										}
									} 
									else 
									{
										alert('Please type the name of the person/institution from whom the purchase was made!');
									}
								} 
								else 
								{
									alert('Please type price for each item purhased!');
								}
							} 
							else 
							{
								alert('Please select the ledger from which the purchase was made (Supplier or Cash Account)!');
							}
						} 
						else 
						{
							alert('Please select the ledger into which the purchase was made (Purchases Account)!');
						};
					});
				}

				function edit_purchase_invoice()
				{
					$(document).on('click','#btn_edit_purchase, #btn_accept_purchase, #btn_display_purchase',function()
					{
						var purchase_id = $(this).attr('data-id');
						var id = $(this).attr('id');
						$.ajax({
				            url:'/layout/vouchers/purchases_edit.php',
				            method:'POST',
				            data:{
								purchase_id:purchase_id,
								id:id
							},
				            datatype:'JSON',
				            success:function(data)
					        {
								var res = $.parseJSON(data);
								if(res[13] > 0)
								{
									var total_amount = res[13];
								}
								else if(res[15] > 0)
								{
									var total_amount = res[15];
								};

								$('#purchase_id').val(res[0]);
								$('#purch_date').val(res[1]);
								$('#purch_dateD').val(res[1]);
								$('#purch_debit').val(res[2]);
								$('#purch_debitD').val(res[2]);
								$('#purch_credit').val(res[3]);
								$('#purch_creditD').val(res[3]);
								$('#purch_amount').val(total_amount);
								$('#purch_amount_2').val(total_amount);
								$('#purch_ref_no').val(res[5]);
								$('#purch_ref_noD').val(res[5]);
								$('#purch_supplied_by').val(res[6]);
								$('#purch_supplied_byD').val(res[6]);
								$('#purch_received_by').val(res[7]);
								$('#purch_received_byD').val(res[7]);
								$('#purch_narration').val(res[8]);
								$('#purch_narrationD').val(res[8]);
								$('#purch_discount_perc').val(res[10]);
								$('#purch_discount_percD').val(res[10]);
								$('#purch_discount_amount').val(res[11]);
								$('#purch_discount_amountD').val(res[11]);
								$('#purchase_items_list').html(res[12]);
								$('#purchase_button_id').val(id);
								$('#purch_warehouse').val(res[14]);
								$('#purch_warehouseD').val(res[14]);

								if(id == 'btn_edit_purchase')
								{
									$('#purch_dateD').prop('hidden', true);
									$('#purch_debitD').prop('hidden', true);
									$('#purch_creditD').prop('hidden', true);
									$('#purch_ref_noD').prop('hidden', true);
									$('#purch_supplied_byD').prop('hidden', true);
									$('#purch_received_byD').prop('hidden', true);
									$('#purch_narrationD').prop('hidden', true);
								};
								
								if(id == 'btn_accept_purchase' || id == 'btn_display_purchase')
								{
									if(id == 'btn_accept_purchase')
									{
										$('#purch_received_by').val(res[9]);
										$('#purch_received_byD').val(res[9]);
										$('#purch_received_by').prop('hidden', false);
										$('#purch_received_byD').prop('hidden', true);
									}
									else if(id == 'btn_display_purchase')
									{
										$('#purch_received_by').prop('hidden', true);
										$('#purch_received_byD').prop('hidden', false);
									};
									$('#purch_narration').prop('hidden', true);
									$('#purch_narrationD').prop('hidden', false);
									$('#purch_date').prop('hidden', true);
									$('#purch_debit').prop('hidden', true);
									$('#purch_credit').prop('hidden', true);
									$('#purch_ref_no').prop('hidden', true);
									$('#purch_supplied_by').prop('hidden', true);

									$('#purch_dateD').prop('hidden', false);
									$('#purch_debitD').prop('hidden', false);
									$('#purch_creditD').prop('hidden', false);
									$('#purch_ref_noD').prop('hidden', false);
									$('#purch_supplied_byD').prop('hidden', false);
								};
								if(id == 'btn_display_purchase')
								{
									$('#purch_update_btn').hide();
								}
								else
								{
									$('#purch_update_btn').show();
								};
								$('#purch_save_btn').hide();
								$('#purchase_create_modal').modal('show');
					        }
				        });
					});
				}

				function update_purchase_invoice()
				{
					$(document).on('click','#purch_update_btn',function(e){
						e.preventDefault();

						var last_tr_id = $("#purchase_items_table tr:last").attr("id");
						var last_tr_select = $("#purchase_items_table tr:last option:selected").val();
						if(last_tr_select =="" || last_tr_select ==0)
						{
							$('#'+last_tr_id+'').remove();
						};
						var purch_debit = $('#purch_debit').val();
						var purch_credit = $('#purch_credit').val();
						var purch_amount = $('#purch_amount').val();
						var purch_supplied_by = $('#purch_supplied_by').val();
						var purch_ref_no = $('#purch_ref_no').val();
						var purch_date = $('#purch_date').val();
						var purch_received_by = $('#purch_received_by').val();
						var purch_narration = $('#purch_narration').val();
						var purch_desc = $('#purch_desc').val();
						if (purch_debit !=="") 
						{
							if (purch_credit !=="") 
							{
								if (purch_amount !=="") 
								{
									if (purch_supplied_by !=="") 
									{
										if (purch_ref_no !=="") 
										{
											if (purch_date !=="") 
											{
												if (purch_received_by !=="") 
												{
													if (purch_desc !=="") 
													{
														$.ajax({
												             url:'/layout/vouchers/purchases_update.php',
												             method:'POST',
												             data:$('#purchases_create_form').serialize(),
												             success:function(data)
													             {
													             	$('#purchases_create_form').trigger('reset');
													             	window.location.href="/layout/vouchers/purchases_list.php";
													             }
												             });
													} 
													else 
													{
														alert('Please select an item purchased!');
													}
												} 
												else 
												{
													alert('Please type the name of the person receiving the goods!');
												}
											} 
											else 
											{
												alert('Please select the date of purchase!');
											}
										} 
										else 
										{
											alert('Please type the supplier invoice number!');
										}
									} 
									else 
									{
										alert('Please type the name of the person/institution from whom the purchase was made!');
									}
								} 
								else 
								{
									alert('Please type price for each item purhased!');
								}
							} 
							else 
							{
								alert('Please select the ledger from which the purchase was made (Supplier or Cash Account)!');
							}
						} 
						else 
						{
							alert('Please select the ledger into which the purchase was made (Purchases Account)!');
						};
					});
				}

