				function get_stock_sales_item_amount()
				{
					$(document).on('keyup', '.stock_sales_item_price, .stock_sales_item_billed_qty', function()
					{  
		       			var i = $(this).attr("data-id");
		       			var qty = $('#stock_sales_item_billed_qty'+i).val();
		       			var price = $('#stock_sales_item_price'+i).val();
		       			var amt = qty * price;
		           		$('#stock_sales_item_amt'+i).val(amt);
		           		$('#stock_sales_item_amtD'+i).val(amt);

						//GROSS_AMOUNT
							var sum=0;
							$('.stock_sales_item_amt').each(function()
							{
								var num = $(this).val().replace(',','');
								if(num !=0)
								{
									sum += parseFloat(num);
								}
							});

							$('#stock_sales_amount').val(sum.toFixed(2));
							$('#stock_sales_amount_2').val(sum.toFixed(2));
							
						//DISCOUNT
							var disc=0;
							$('.stock_sales_item_disc_amt').each(function()
							{
								var num = $(this).val().replace(',','');
								if(num !=0)
								{
									disc += parseFloat(num);
								}
							});
							
							$('#stock_sales_discount_amount').val(disc.toFixed(2));
							$('#stock_sales_discount_amountD').val(disc.toFixed(2));

						//NET_AMOUNT
							var net = sum - disc;
							$('#stock_sales_net_amount').val(net.toFixed(2));
							$('#stock_sales_net_amountD').val(net.toFixed(2));
		           	});
				}

				function get_stock_sales_item_discount()
				{
					$(document).on('keyup', '.stock_sales_item_disc_perc, .stock_sales_item_disc_amt', function()
					{  
		       			var i = $(this).attr("data-id");
		       			var item_amt = $('#stock_sales_item_amt'+i).val();
		       			var disc_perc = $('#stock_sales_item_disc_perc'+i).val();
		       			var disc_amt = $('#stock_sales_item_disc_amt'+i).val();

						if(disc_perc > 0 && item_amt > 0)
						{
							var discount = disc_perc * item_amt;
						}
						else if(disc_perc == '' && disc_amt > 0 && item_amt > 0)
						{
							var discount = disc_amt;
						};

						var discount = parseFloat(discount).toFixed(2)
		       			$('#stock_sales_item_disc_amt'+i).val(discount);
		           		
						//GROSS_AMOUNT
							var sum=0;
							$('.stock_sales_item_amt').each(function()
							{
								var num = $(this).val().replace(',','');
								if(num !=0)
								{
									sum += parseFloat(num);
								}
							});
							
						//DISCOUNT
							var disc=0;
							$('.stock_sales_item_disc_amt').each(function()
							{
								var num = $(this).val().replace(',','');
								if(num !=0)
								{
									disc += parseFloat(num);
								}
							});
							
							$('#stock_sales_discount_amount').val(disc.toFixed(2));
							$('#stock_sales_discount_amountD').val(disc.toFixed(2));

						//NET_AMOUNT
							var net = sum - disc;
							$('#stock_sales_net_amount').val(net.toFixed(2));
							$('#stock_sales_net_amountD').val(net.toFixed(2));
		           	});
				}

