									//DISCOUNT
										var disc=0;
										$('.stock_sales_item_disc_amt').each(function()
										{
											var num = $(this).val().replace(',','');
											if(num !=0)
											{
												disc += parseFloat(num);
											}
										});
										
										$('#stock_sales_discount_amount').val(disc.toFixed(2));
										$('#stock_sales_discount_amountD').val(disc.toFixed(2));

									//NET_AMOUNT
										var net = sum - disc;
										$('#stock_sales_net_amount').val(net.toFixed(2));
										$('#stock_sales_net_amountD').val(net.toFixed(2));

									//$('#stock_sales_conversion_item_search_msg').html('<h6 style=color:green;>The '+stock_item+' has been ADDED</h6>');
									//$('#stock_sales_conversion_item_search_msg').hide().slideDown().delay(2000).fadeOut();
									$('#sstock_sales_search_item_qty'+x).val('');
									$('#stock_sales_search_items_list').html('');
									$('#stock_sales_search_item').val('');
									$('#stock_sales_search_item').focus();
