				function save_stock_sales()
				{
					$(document).on('click','#stock_sales_save_btn',function(e)
					{
						e.preventDefault();
						var last_tr_id = $("#stock_sales_items_table tr:last").attr("id");
						var payment_option_total = $('#payment_option_total').val();
						var type = $('#stock_sales_invoice_type').val();
						var warehouse_id = $('#stock_sales_warehouse_id').val();
						var amount = $('#stock_sales_amount').val();
						var discount_amount = $('#stock_sales_discount_amount').val();
						var net_amount = $('#stock_sales_net_amount').val();
						var customer_name = $('#stock_sales_customer_name').val();
						var stock_sales_date = $('#stock_sales_date').val();
						var membership_no = $('#stock_sales_membership_no').val();
						var insurance_company = $('#stock_sales_insurance_company').val();
						var buying_branch = $('#stock_sales_buying_branch').val();

						if (last_tr_id > 1) 
						{
							if (net_amount == payment_option_total) 
							{
								if (customer_name !="") 
								{
									if (stock_sales_date !="") 
									{
										if (warehouse_id !="" && warehouse_id > 0) 
										{
											if((type == 'new_branch_sales_invoice' && buying_branch > 0) || (type != 'new_branch_sales_invoice' && buying_branch == 0))
											{
												if((type == 'new_corporate_sales_invoice' && membership_no != '' && insurance_company > 0) || (type != 'new_corporate_sales_invoice'))
												{
													$.ajax({
														url:'/layout/vouchers/stock_sales_save.php',
														method:'POST',
														data:$('#stock_sales_create_form').serialize(),
														success:function(data)
														{
															$('#stock_sales_create_form').trigger('reset');
															$('#stock_sales_create_modal').modal('hide');
															if(type == 'new_branch_sales_invoice')
															{
																window.open('/layout/vouchers/stock_sales_invoice_pdf_A4.php', '_blank');
															}
															else
															{
																window.open('/layout/vouchers/stock_sales_invoice_pdf.php', '_blank');
															};
														}
													});
												} 
												else 
												{
													alert('Please provide the membership and select the Company name!');
												};
											} 
											else 
											{
												alert('Please select the buying Branch!');
											};
										} 
										else 
										{
											alert('Please select the Warehouse!');
										};
									} 
									else 
									{
										alert('Please select the date of sales!');
									};
								} 
								else 
								{
									alert('Please type the name of the customer!');
								}
							} 
							else 
							{
								alert('Please the invoice total and payment total must be equal!');
							};
						} 
						else 
						{
							alert('Please select one or more items to sell!');
						};
					});
				}

