				function stock_sales_invoice_check_negative()
				{
					$(document).on('keyup','#batch_qty_issue',function()
					{
						var block_negative = $('#batch_qty_block_negative').val();
						var batch_no = $('#batch_qty_batch_no').val();
						var qty = parseInt($(this).val());
						var batch_bal = parseInt($('#batch_qty_batch_balance').val());
						var item_bal = parseInt($('#batch_qty_item_balance').val());
						if(block_negative =='Yes')
						{
							if(batch_no != '' && batch_no !=0 && batch_no !='0')
							{
								if(qty > item_bal)
								{
									alert('Please the Quantity:'+qty+' is more than the Batch Balance:'+item_bal+'!');
									$('#batch_qty_issue').val('');
								}
								else if(qty <= item_bal && qty > batch_bal)
								{
									alert('Please the Quantity:'+qty+' is more than the Batch Balance:'+batch_bal+'!');
									$('#batch_qty_issue').val('');
								};
							}
							else
							{
								if(qty > item_bal)
								{
									alert('Please the Quantity:'+qty+' is more than the Batch Balance:'+item_bal+'!');
									$('#batch_qty_issue').val('');
								};
							};
						};
					});
				}

				function add_stock_sales_invoice_item_row()
				{
					$(document).on('click','#btn_add_stock_sales_invoice_item, #btn_stock_sales_invoice_batch_qty_save',function(){
						
						var count = $('#stock_sales_invoiceTable tr:last').attr('id');
						/*var stock_item_id = $(this).attr('data-id');
						var stock_item = $(this).attr('data-id1');
						var price = $(this).attr('data-id2');
						var i = $(this).closest('tr').attr('id');
						var qty = $('#item_search_qty'+i).val();*/
						var stock_item_id = $('#batch_qty_stock_item_id').val();
						var stock_item = $('#batch_qty_stock_item').val();
						var price = $('#batch_qty_price').val();
						var qty = $('#batch_qty_issue').val();
						var qty_billed = $('#batch_qty_billed').val();
						var disc_perc = $('#batch_disc_perc').val();
						var disc_amount = $('#batch_disc_amount').val();
						var batch_no = $('#batch_qty_batch_no').val();
						var insurance = $('#customer_insurance').val();
						
						var amount = qty * price;
						if(qty !='' && qty > 0)
						{
							$.ajax({
								url:'/layout/vouchers/stock_sales_invoice_item_search_save.php',
								method:'POST',
								data:{
									stock_item_id:stock_item_id,
									stock_item:stock_item,
									qty:qty,
									qty_billed:qty_billed,
									disc_perc:disc_perc,
									disc_amount:disc_amount,
									price:price,
									amount:amount,
									batch_no:batch_no,
									insurance:insurance,
									count:count
								},
								datatype:'JSON',
								success:function(data)
								{
									$('#stock_sales_invoice_batch_qty_form').trigger('reset');
									$('#stock_sales_invoice_batch_qty_modal').modal('hide');
									$('#stock_sales_invoiceTable').append(data);

									var sum = 0;
									$(".stock_sales_invoice_item_amount").each(function()
									{
										sum += +$(this).val();
									});
									$("#stock_sales_invoice_sub_total").val(sum.toFixed(2));
									$("#stock_sales_invoice_sub_totalD").val(sum.toFixed(2));

									var disc = 0;
									$(".stock_sales_invoice_item_disc_amount").each(function()
									{
										disc += +$(this).val();
									});
									$("#stock_sales_invoice_discount").val(disc.toFixed(2));
									$("#stock_sales_invoice_discountD").val(disc.toFixed(2));

									var net = sum - disc;
									$("#stock_sales_invoice_net_total").val(net.toFixed(2));
									$("#stock_sales_invoice_net_totalD").val(net.toFixed(2));

									$("#stock_sales_invoice_item_search").val('');
									$("#stock_sales_invoice_item_search").focus();
								}
							});
						}
						else
						{
							alert('Please the quantity cannot be EMPTY!');
						};
					});
				}

