				function stock_sales_invoice_label_modal()
				{
					$(document).on('click','#label_stock_sales_invoice',function()
					{
						var sales_item_id = $(this).attr('data-id');
						var stock_item_id = $(this).attr('data-id1');
						var date = $(this).attr('data-id2');
						$.ajax({  
								url:'/layout/vouchers/stock_sales_invoice_label_open.php',  
								method:'POST',  
								data:{
									sales_item_id:sales_item_id,
									stock_item_id:stock_item_id
								},
								datatype: 'JSON',
								success:function(data){
									var res = $.parseJSON(data);
									$('#label_view').val(res[0]);
									$('#label_warning').val(res[1]);
									$('#label_sales_item_id').val(res[2]);
									$('#label_dispensed_by').val(res[3]);
									$('#label_date').val(date);
									$('#stock_sales_invoice_label_modal').modal('show');
								}  
							});
					});
				}

				function stock_sales_invoice_label_save()
				{
					$(document).on('click','#btn_stock_sales_invoice_label_save',function(){
						var label_dispensed_by = $('#label_dispensed_by').val();
						var label_view = $('#label_view').val();
						var label_warning = $('#label_warning').val();
						var sales_item_id = $('#label_sales_item_id').val();
						var date = $('#label_date').val();
						if (label_dispensed_by != "") 
						{
							if(label_view != "")
							{
								$.ajax(
								{
									url: '/layout/vouchers/stock_sales_invoice_label_save.php',
									method: 'POST',
									data:{
										label_dispensed_by:label_dispensed_by,
										label_view:label_view,
										label_warning:label_warning,
										sales_item_id:sales_item_id,
										date:date
									},
									success: function(data)
									{
										$('#stock_sales_invoice_label_form').trigger('reset');
										$('#stock_sales_invoice_label_modal').modal('hide');
										window.open('/layout/vouchers/stock_sales_invoice_label_display.php', '_blank');
									}
								});
							}
							else
							{
								alert('Please the label cannot be EMPTY!');
							}
						} 
						else 
						{
							alert('Please The Dispense/Label by cannot be EMPTY!');
						}
					});
				}

