		function sales_returns_enter_qty_and_amount()
		{
			$(document).on('keyup','.stock_sales_returns_qty, .stock_sales_returns_price',function()
			{
				var i = $(this).attr('data-id');
				if(isNaN($(this).val()))
				{
					var qty = 0;
				}
				else
				{
					var qty = parseFloat($(this).val());
				};

				var price = parseFloat($('#stock_sales_returns_price'+i).val());
				var amount = parseFloat(qty * price);

				if(qty > 0 && price > 0)
				{
					$('#stock_sales_returns_amt'+i).val(amount);
					$('#stock_sales_returns_amtD'+i).val(amount);
					var sum = 0;
					$(".stock_sales_returns_amt").each(function()
					{
						sum += +$(this).val();
					});
					$("#stock_sales_returns_amount").val(sum);
					$("#stock_sales_returns_amountD").val(sum);
				};
			});
		}

		function sales_returns_save()
		{
			$(document).on('click','#stock_sales_returns_save_btn',function(e)
			{
				e.preventDefault();
				var credit_ledger = $('#stock_sales_returns_credit_ledger').val();
				var amount = $('#stock_sales_returns_amount').val();
				var reason = $('#stock_sales_returns_reason').val();
				var date = $('#stock_sales_returns_date').val();
				if (credit_ledger > 0)
				{
					if (amount > 0)
					{
						if (reason !='')
						{
							if (date !='')
							{
								$.ajax({
									url:'/layout/vouchers/sales_returns_save.php',
									method:'POST',
									data:$('#stock_sales_returns_create_form').serialize(),
									success:function()
									{
										$('#stock_sales_returns_create_form').trigger('reset');
										$('#stock_sales_returns_create_modal').modal('hide');
										window.location.href="/layout/vouchers/sales_returns_list.php";
									}
								});	
							} 
							else 
							{
								$('#stock_sales_returns_create_form_msg').html('<h6 style=color:red;>Please the Date cannot be EMPTY!</h6>');
								$('#stock_sales_returns_create_form_msg').hide().slideDown().delay(2000).fadeOut();
							};
						} 
						else 
						{
							$('#stock_sales_returns_create_form_msg').html('<h6 style=color:red;>Please the Reason cannot be EMPTY!</h6>');
							$('#stock_sales_returns_create_form_msg').hide().slideDown().delay(2000).fadeOut();
						};
					} 
					else 
					{
						$('#stock_sales_returns_create_form_msg').html('<h6 style=color:red;>Please set qty and price for at least one item!</h6>');
						$('#stock_sales_returns_create_form_msg').hide().slideDown().delay(2000).fadeOut();
					};
				} 
				else 
				{
					$('#stock_sales_returns_create_form_msg').html('<h6 style=color:red;>Please the Credit Ledger cannot be EMPTY!</h6>');
					$('#stock_sales_returns_create_form_msg').hide().slideDown().delay(2000).fadeOut();
				};
			});
		}

