				function post_stock_requisition_voucher()
				{
					$(document).on('click','#stock_requisition_auto_post_btn',function(e)
					{
						e.preventDefault();
						var warehouse_id = $('#stock_requisition_auto_warehouse_id').val();
						var start_date = $('#stock_requisition_auto_start_date').val();
						var end_date = $('#stock_requisition_auto_end_date').val();
						if (warehouse_id !="" && warehouse_id > 0) 
						{
							if (start_date !="") 
							{
								if (end_date != "") 
								{
									if (end_date >= start_date) 
									{
										$.ajax({
											url:'/layout/vouchers/stock_requisition_auto_post.php',
											method:'POST',
											data:$('#stock_requisition_auto_modal_form').serialize(),
									        datatype:'JSON',
											success:function(data)
											{
										        var res = $.parseJSON(data);
												$('#stock_requisition_auto_modal_form').trigger('reset');
												$('#stock_requisition_auto_modal').modal('hide');
												$('#stock_requisition_items_list').html(res[0]);
												$('#stock_req_from').val(res[1]);
												$('#stock_req_fromD').val(res[1]);
												$('#stock_req_to').val(res[2]);
												$('#stock_req_toD').val(res[2]);
												$('#stk_req_requested_by').val(res[4]);
												$('#stk_req_requested_byD').val(res[4]);
												$('#stk_req_narration').val(res[3]);
												$('#stk_req_narrationD').val(res[3]);
												$('#stock_req_from').prop('hidden', true);
												$('#stock_req_fromD').prop('hidden', false);
												$('#stock_req_to').prop('hidden', true);
												$('#stock_req_toD').prop('hidden', false);
												$('#stk_req_date').prop('hidden', true);
												$('#stk_req_dateD').prop('hidden', false);

												$('#stock_req_update_btn').hide();
												$('#stock_req_save_btn').show();
												$('#stock_requisition_create_modal').modal('show');
											}
										});
									} 
									else 
									{
										alert('Please the Start Date cannot be less than the End Date!');
									};
								} 
								else 
								{
									alert('Please the End Date cannot be EMPTY!');
								};
							} 
							else 
							{
								alert('Please the Start Date cannot be EMPTY!');
							}
						} 
						else 
						{
							alert('Please the Warehouse cannot be EMPTY!');
						};
					});
				}

