		function stock_take_invoice_add_qty()
		{
			$(document).on('click','#btn_add_qty_stock_take_invoice_item',function(e){
				e.preventDefault();
				var stock_item_id = $(this).attr('data-id');
				var stock_item_name = $(this).attr('data-id1');
				var stock_item_price = $(this).attr('data-id2');
				var maintain_batch = $(this).attr('data-id3');
				var block_negative = $(this).attr('data-id4');
				var item_balance = $(this).attr('data-id5');
				var warehouse_id = $('#stock_take_store').val();
				$.ajax({
					url:'/layout/vouchers/stock_take_invoice_add_qty.php',
					method:'POST',
					data:{
						stock_item_id:stock_item_id,
						maintain_batch:maintain_batch,
						block_negative:block_negative,
						warehouse_id:warehouse_id
					},
					datatype:'JSON',
					success:function(data)
					{
						var res = $.parseJSON(data);
						$('#stock_take_invoice_batch_qty_modal_title').text(stock_item_name);
						$('#stock_take_invoice_batch_qty_form').trigger('reset');
						$('#stock_take_invoice_batch_qty_batch_expiry_list').html(res[0]);
						$('#stock_take_batch_qty_batch_no_div').html(res[1]);
						$('#stock_take_batch_qty_maintain_batch').val(maintain_batch);
						$('#stock_take_batch_qty_block_negative').val(block_negative);
						$('#stock_take_batch_qty_item_balance').val(item_balance);
						$('#stock_take_batch_qty_price').val(stock_item_price);
						$('#stock_take_batch_qty_stock_item_id').val(stock_item_id);
						$('#stock_take_batch_qty_stock_item').val(stock_item_name);
						$('#stock_take_invoice_batch_qty_modal').modal('show');
					}
				});
			});
		}

